public class Main {
    public static void main(String[] args) {
        int day = 6;              // 6 = Saturday, 7 = Sunday
        boolean onHoliday = false;

        boolean weekend = day == 6 || day == 7;
        boolean dayOff = weekend || onHoliday;
        boolean working = !dayOff;

        System.out.println("Weekend: " + weekend);
        System.out.println("Day off: " + dayOff);
        System.out.println("Working: " + working);
    }
}

