import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("How many people? ");
        int people = scanner.nextInt();

        System.out.print("Total bill? ");
        int bill = scanner.nextInt();

        // If people is 0, the division on the right is never run.
        boolean affordable = people > 0 && bill / people <= 500;

        System.out.println("Affordable each: " + affordable);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Marks out of 100? ");
        int marks = scanner.nextInt();

        System.out.print("Attendance percent? ");
        int attendance = scanner.nextInt();

        boolean passedMarks = marks >= 40;
        boolean goodAttendance = attendance >= 75;
        boolean distinction = marks >= 75 && goodAttendance;

        System.out.println("Passed marks:     " + passedMarks);
        System.out.println("Good attendance:  " + goodAttendance);
        System.out.println("Gets certificate: " + (passedMarks && goodAttendance));
        System.out.println("With distinction: " + distinction);
    }
}

